--
-- Estructura de tabla para la tabla `participante`
--

CREATE TABLE `participante` (
  `ID` int(11) NOT NULL,
  `ID_Evento` int(11) DEFAULT NULL,
  `Sucursal` varchar(100) CHARACTER SET utf8mb4 DEFAULT NULL,
  `Vendedor` varchar(100) CHARACTER SET utf8mb4 DEFAULT NULL,
  `Nombre` varchar(255) CHARACTER SET utf8mb4 DEFAULT NULL,
  `Proveedor` varchar(255) CHARACTER SET utf8mb4 DEFAULT NULL,
  `QR_Code` varchar(255) CHARACTER SET utf8mb4 DEFAULT NULL,
  `Telefono` varchar(15) CHARACTER SET utf8mb4 NOT NULL,
  `Ruta_Gafete` varchar(255) CHARACTER SET utf8mb4 DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

